def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="dq",
        description="Data quality rule validation and lineage tracing.",
    )
    subparsers = parser.add_subparsers(dest="command", required=True)

    validate_parser = subparsers.add_parser(
        "validate",
        help="validate records from a UTF-8 JSON object on standard input",
    )
    validate_parser.set_defaults(handler=_run_validate)

    lineage_parser = subparsers.add_parser(
        "lineage",
        help="trace upstream/downstream lineage from a UTF-8 JSON object "
        "on standard input",
    )
    lineage_parser.set_defaults(handler=_run_lineage)

    field_lineage_parser = subparsers.add_parser(
        "field-lineage",
        help="trace upstream/downstream field-level lineage from a UTF-8 "
        "JSON object on standard input",
    )
    field_lineage_parser.set_defaults(handler=_run_field_lineage)

    lineage_paths_parser = subparsers.add_parser(
        "lineage-paths",
        help="explain ordered upstream/downstream lineage paths from a "
        "UTF-8 JSON object on standard input",
    )
    lineage_paths_parser.set_defaults(handler=_run_lineage_paths)

    field_lineage_paths_parser = subparsers.add_parser(
        "field-lineage-paths",
        help="explain ordered upstream/downstream field-level lineage paths "
        "from a UTF-8 JSON object on standard input",
    )
    field_lineage_paths_parser.set_defaults(handler=_run_field_lineage_paths)

    correlate_parser = subparsers.add_parser(
        "correlate",
        help="group violation results into cross-rule correlation events "
        "from a UTF-8 JSON object on standard input",
    )
    correlate_parser.set_defaults(handler=_run_correlate)

    correlate_links_parser = subparsers.add_parser(
        "correlate-links",
        help="group violation results across linked samples into "
        "cross-dataset correlation events from a UTF-8 JSON object on "
        "standard input",
    )
    correlate_links_parser.set_defaults(handler=_run_correlate_links)

    violation_origins_parser = subparsers.add_parser(
        "violation-origins",
        help="analyze upstream/self origin and downstream impact evidence "
        "of violated targets from a UTF-8 JSON object on standard input",
    )
    violation_origins_parser.set_defaults(handler=_run_violation_origins)

    field_impact_parser = subparsers.add_parser(
        "field-impact",
        help="analyze downstream field-level quality impact from a UTF-8 "
        "JSON object on standard input",
    )
    field_impact_parser.set_defaults(handler=_run_field_impact)

    query_results_parser = subparsers.add_parser(
        "query-results",
        help="filter complete composite rule results by rule id, severity "
        "or record locator from a UTF-8 JSON object on standard input",
    )
    query_results_parser.set_defaults(handler=_run_query_results)

    snapshot_diff_parser = subparsers.add_parser(
        "snapshot-diff",
        help="compare violated results of two quality check snapshots over "
        "the shared lineage graph from a UTF-8 JSON object on standard "
        "input",
    )
    snapshot_diff_parser.set_defaults(handler=_run_snapshot_diff)

    reference_integrity_parser = subparsers.add_parser(
        "reference-integrity",
        help="validate cross-dataset reference integrity rules from a "
        "UTF-8 JSON object on standard input",
    )
    reference_integrity_parser.set_defaults(handler=_run_reference_integrity)
    return parser


def main(argv: Optional[List[str]] = None) -> int:
    parser = build_parser()
    args = parser.parse_args(argv)
    return args.handler()


if __name__ == "__main__":
    sys.exit(main())

"""End-to-end tests for the ``dq reference-integrity`` command line interface."""

import json
import subprocess
import sys
import unittest


PKG = [sys.executable, "-m", "data_quality", "reference-integrity"]


def run_cli(payload_bytes):
    return subprocess.run(
        PKG,
        input=payload_bytes,
        capture_output=True,
    )


def run_json(obj):
    return run_cli(json.dumps(obj, ensure_ascii=False).encode("utf-8"))


PAYLOAD = {
    "datasets": {
        "customers": [{"id": "c1"}, {"id": "c2"}],
        "orders": [
            {"id": "o1", "customer_id": "c1"},
            {"id": "o2", "customer_id": "c9"},
            {"id": "o3", "customer_id": None},
        ],
    },
    "rules": [
        {
            "rule_id": "订单-客户",
            "source_dataset": "orders",
            "source_field": "customer_id",
            "target_dataset": "customers",
            "target_field": "id",
        }
    ],
}


class CliReferenceIntegritySuccessTest(unittest.TestCase):
    def test_violation_output(self):
        proc = run_json(PAYLOAD)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        body = json.loads(proc.stdout.decode("utf-8"))
        self.assertEqual(
            body,
            {
                "passed": False,
                "summary": {
                    "dataset_count": 2,
                    "rule_count": 1,
                    "checked_value_count": 2,
                    "violation_count": 1,
                },
                "violations": [
                    {
                        "rule_id": "订单-客户",
                        "source": {
                            "dataset": "orders",
                            "record_index": 1,
                            "record_id": "o2",
                            "field": "customer_id",
                            "value": "c9",
                        },
                        "target": {"dataset": "customers", "field": "id"},
                        "message": "has no matching target value",
                    }
                ],
            },
        )

    def test_output_is_a_single_line(self):
        proc = run_json(PAYLOAD)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertEqual(len(proc.stdout.decode("utf-8").splitlines()), 1)

    def test_passed_output(self):
        payload = {
            "datasets": {
                "customers": [{"id": "c1"}],
                "orders": [{"customer_id": "c1"}],
            },
            "rules": PAYLOAD["rules"],
        }
        proc = run_json(payload)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        body = json.loads(proc.stdout.decode("utf-8"))
        self.assertTrue(body["passed"])
        self.assertEqual(body["violations"], [])


class CliReferenceIntegrityErrorTest(unittest.TestCase):
    def assert_error(self, proc, code):
        self.assertEqual(proc.returncode, 2, proc.stdout)
        body = json.loads(proc.stdout.decode("utf-8"))
        self.assertIn(code, body["error"]["code"])
        self.assertIn("message", body["error"])

    def test_invalid_json(self):
        proc = run_cli(b"{not json")
        self.assert_error(proc, "INVALID_JSON")

    def test_payload_not_object(self):
        proc = run_json([1, 2])
        self.assert_error(proc, "INVALID_REFERENCE_INPUT")

    def test_missing_datasets(self):
        proc = run_json({"rules": []})
        self.assert_error(proc, "INVALID_REFERENCE_INPUT")

    def test_record_not_object(self):
        proc = run_json({"datasets": {"a": [1]}, "rules": []})
        self.assert_error(proc, "INVALID_REFERENCE_INPUT")

    def test_rule_missing_key(self):
        payload = {
            "datasets": {},
            "rules": [{"rule_id": "r1"}],
        }
        proc = run_json(payload)
        self.assert_error(proc, "INVALID_REFERENCE_RULE")

    def test_duplicate_rule_id(self):
        rule = dict(PAYLOAD["rules"][0])
        proc = run_json(
            {"datasets": PAYLOAD["datasets"], "rules": [rule, dict(rule)]}
        )
        self.assert_error(proc, "INVALID_REFERENCE_RULE")

    def test_unknown_dataset(self):
        proc = run_json({"datasets": {}, "rules": PAYLOAD["rules"]})
        self.assert_error(proc, "UNKNOWN_REFERENCE_DATASET")


if __name__ == "__main__":
    unittest.main()

"""Unit tests for cross-dataset reference integrity validation."""

import unittest

from data_quality.reference_integrity import (
    InvalidReferenceInputError,
    InvalidReferenceRuleError,
    UnknownReferenceDatasetError,
    validate_references,
)


def rule(
    rule_id,
    source_dataset="orders",
    source_field="customer_id",
    target_dataset="customers",
    target_field="id",
):
    return {
        "rule_id": rule_id,
        "source_dataset": source_dataset,
        "source_field": source_field,
        "target_dataset": target_dataset,
        "target_field": target_field,
    }


DATASETS = {
    "customers": [
        {"id": "c1", "name": "甲"},
        {"id": "c2", "name": "乙"},
    ],
    "orders": [
        {"id": "o1", "customer_id": "c1"},
        {"id": "o2", "customer_id": "c9"},
        {"id": "o3", "customer_id": None},
        {"id": "o4"},
    ],
}


class ValidateReferencesSuccessTest(unittest.TestCase):
    def test_violation_shape_and_summary(self):
        result = validate_references(DATASETS, [rule("ref-1")])
        self.assertEqual(
            result,
            {
                "passed": False,
                "summary": {
                    "dataset_count": 2,
                    "rule_count": 1,
                    "checked_value_count": 2,
                    "violation_count": 1,
                },
                "violations": [
                    {
                        "rule_id": "ref-1",
                        "source": {
                            "dataset": "orders",
                            "record_index": 1,
                            "record_id": "o2",
                            "field": "customer_id",
                            "value": "c9",
                        },
                        "target": {"dataset": "customers", "field": "id"},
                        "message": "has no matching target value",
                    }
                ],
            },
        )

    def test_passed_when_all_match(self):
        datasets = {
            "customers": [{"id": "c1"}, {"id": "c2"}],
            "orders": [
                {"customer_id": "c1"},
                {"customer_id": "c2"},
                {"customer_id": None},
                {},
            ],
        }
        result = validate_references(datasets, [rule("ref-1")])
        self.assertTrue(result["passed"])
        self.assertEqual(result["violations"], [])
        self.assertEqual(result["summary"]["checked_value_count"], 2)

    def test_record_id_defaults_to_null(self):
        datasets = {
            "customers": [{"id": "c1"}],
            "orders": [{"customer_id": "nope"}],
        }
        result = validate_references(datasets, [rule("ref-1")])
        self.assertIsNone(result["violations"][0]["source"]["record_id"])

    def test_rules_execute_in_array_order(self):
        datasets = {
            "a": [{"f": 1}],
            "b": [{"g": 2}],
            "c": [{"h": 3}],
        }
        rules = [
            rule("r2", "b", "g", "a", "f"),
            rule("r1", "a", "f", "c", "h"),
        ]
        result = validate_references(datasets, rules)
        self.assertEqual(
            [v["rule_id"] for v in result["violations"]], ["r2", "r1"]
        )

    def test_json_equality_bool_is_not_number(self):
        datasets = {
            "a": [{"f": True}],
            "b": [{"g": 1}],
        }
        result = validate_references(
            datasets, [rule("r1", "a", "f", "b", "g")]
        )
        self.assertEqual(result["summary"]["violation_count"], 1)

    def test_json_equality_containers(self):
        datasets = {
            "a": [{"f": {"x": [1, 2]}}],
            "b": [{"g": {"x": [1, 2]}}, {"g": {"x": [2, 1]}}],
        }
        result = validate_references(
            datasets, [rule("r1", "a", "f", "b", "g")]
        )
        self.assertTrue(result["passed"])

    def test_target_record_missing_field_never_matches(self):
        datasets = {
            "a": [{"f": None}],
            "b": [{"other": 1}],
        }
        result = validate_references(
            datasets, [rule("r1", "a", "f", "b", "g")]
        )
        self.assertTrue(result["passed"])
        self.assertEqual(result["summary"]["checked_value_count"], 0)

    def test_zero_source_value_is_checked(self):
        datasets = {
            "a": [{"f": 0}],
            "b": [{"g": 1}],
        }
        result = validate_references(
            datasets, [rule("r1", "a", "f", "b", "g")]
        )
        self.assertEqual(result["summary"]["checked_value_count"], 1)
        self.assertEqual(result["summary"]["violation_count"], 1)


class ValidateReferencesInputErrorTest(unittest.TestCase):
    def test_datasets_not_object(self):
        with self.assertRaises(InvalidReferenceInputError):
            validate_references([], [])

    def test_dataset_not_array(self):
        with self.assertRaises(InvalidReferenceInputError):
            validate_references({"a": {}}, [])

    def test_record_not_object(self):
        with self.assertRaises(InvalidReferenceInputError):
            validate_references({"a": [[1]]}, [])

    def test_rules_not_array(self):
        with self.assertRaises(InvalidReferenceInputError):
            validate_references({}, {})


class ValidateReferencesRuleErrorTest(unittest.TestCase):
    def test_rule_not_object(self):
        with self.assertRaises(InvalidReferenceRuleError):
            validate_references({}, ["r1"])

    def test_rule_missing_key(self):
        bad = rule("r1")
        del bad["target_field"]
        with self.assertRaises(InvalidReferenceRuleError):
            validate_references({}, [bad])

    def test_rule_extra_key(self):
        bad = rule("r1")
        bad["extra"] = 1
        with self.assertRaises(InvalidReferenceRuleError):
            validate_references({}, [bad])

    def test_rule_empty_field(self):
        bad = rule("r1", source_field="")
        with self.assertRaises(InvalidReferenceRuleError):
            validate_references({}, [bad])

    def test_rule_non_string_field(self):
        bad = rule("r1", target_dataset=None)
        with self.assertRaises(InvalidReferenceRuleError):
            validate_references({}, [bad])

    def test_duplicate_rule_id(self):
        with self.assertRaises(InvalidReferenceRuleError):
            validate_references(
                {}, [rule("r1"), rule("r1", source_field="other")]
            )


class ValidateReferencesUnknownDatasetTest(unittest.TestCase):
    def test_unknown_source_dataset(self):
        with self.assertRaises(UnknownReferenceDatasetError):
            validate_references(
                {"customers": []}, [rule("r1", source_dataset="nope")]
            )

    def test_unknown_target_dataset(self):
        with self.assertRaises(UnknownReferenceDatasetError):
            validate_references(
                {"orders": []}, [rule("r1", target_dataset="nope")]
            )


if __name__ == "__main__":
    unittest.main()

